-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Personajes de Genshin Impact: 119. Cada fila lleva todo: datos, icono, biografia y
-- materiales de ascension.
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.

insert into public.characters (
  id, game_id, name, image_url, rarity, element, level_cap, description, role, path, signature, is_upcoming, biography, biography_source, biography_en, biography_source_en, biography_es, biography_source_es, biography_es_translated, ascension
)
values
  ('gi-aino', 'genshin-impact', 'Aino', 'https://enka.network/ui/UI_AvatarIcon_Aino.png', '4', 'Hydro', 90, null, 'Sub-DPS / Support', null, null, false, 'The genius mechanical inventor of Nod-Krai. She lives in the Clink-Clank Krumkake Craftshop, surrounded by her mechanical family and the fragrance of the workshop''s namesake — scrumptious krumkakes.

Located at the border, Nod-Krai is neither a land of abundance nor a place of joy. All year round, the cold wind howls and lashes the lands, as though attempting to wring even the last dregs of warmth from every corner.

Yet in this seemingly forgotten corner of the world, the marketplace is chock-a-block with an astonishing array of marvelous machines. From guns that shoot flowers to floor sweepers that act as affectionate as puppies... You never know how a contraption might act until the very moment it springs to life.', 'https://genshin-impact.fandom.com/wiki/Aino%2FProfile', 'The genius mechanical inventor of Nod-Krai. She lives in the Clink-Clank Krumkake Craftshop, surrounded by her mechanical family and the fragrance of the workshop''s namesake — scrumptious krumkakes.

Located at the border, Nod-Krai is neither a land of abundance nor a place of joy. All year round, the cold wind howls and lashes the lands, as though attempting to wring even the last dregs of warmth from every corner.

Yet in this seemingly forgotten corner of the world, the marketplace is chock-a-block with an astonishing array of marvelous machines. From guns that shoot flowers to floor sweepers that act as affectionate as puppies... You never know how a contraption might act until the very moment it springs to life.', 'https://genshin-impact.fandom.com/wiki/Aino%2FProfile', '"¿Que cómo puedes entablar una amistad con Aino? Procediendo a analizar datos... Respuesta: primero, debes estar en contra de los krumkakes salados; segundo, debes apreciar sus inventos; y tercero, debes jugar con ella a menudo".
La primera impresión que tiene la gente de la tierra fronteriza de Nod Krai es que es “un lugar caótico azotado por un viento gélido”. Sin embargo, una vez que te familiarizas con sus reglas y exploras este lugar pacientemente, te darás cuenta de que está lleno de objetos curiosos y maravillosos. Es posible que, mientras estás de compras, te encuentres con una chica robot que está comprando como una persona cualquiera, o que escuches el estruendoso sonido de una forja al pasar por un mercado. Con un poco de suerte, hasta podrías encontrarte con un robot que pasa a toda velocidad. Si preguntas a alguien, averiguarás que todas esas máquinas son obra de Aino.

Si todo ello te da curiosidad y quieres visitar a Aino, hazlo, es muy sencillo.', 'https://genshin-impact.fandom.com/es/wiki/Aino%2FHistoria', false, '[{"desde":20,"hasta":40,"creditos":20000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101257.png","nombre":"Rodamiento portátil","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104121.png","nombre":"Pedacito de lazurita varunada","cantidad":1},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","nombre":"Eje dañado","cantidad":3}]},{"desde":40,"hasta":50,"creditos":40000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101257.png","nombre":"Rodamiento portátil","cantidad":10},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104122.png","nombre":"Fragmento de lazurita varunada","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","nombre":"Eje dañado","cantidad":15},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113077.png","nombre":"Troquel de “estam-pato” de kuuvahki preciso","cantidad":2}]},{"desde":50,"hasta":60,"creditos":60000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101257.png","nombre":"Rodamiento portátil","cantidad":20},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104122.png","nombre":"Fragmento de lazurita varunada","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","nombre":"Eje reforzado","cantidad":12},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113077.png","nombre":"Troquel de “estam-pato” de kuuvahki preciso","cantidad":4}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101257.png","nombre":"Rodamiento portátil","cantidad":30},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104123.png","nombre":"Trozo de lazurita varunada","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","nombre":"Eje reforzado","cantidad":18},{"icono":"https://gi.ya