  ('gi-collei', 'genshin-impact', 'Collei', 'https://enka.network/ui/UI_AvatarIcon_Collei.png', '4', 'Dendro', 90, null, 'Sub-DPS / Support', null, null, false, 'A Trainee Forest Ranger who is under the tutelage of Tighnari. She started her academic career a little later than her peers, so she is currently working hard to catch up. She hides the other side of her personality deep under the surface of optimism and kindness.

"Helpful," "bright and sunny," "friendly and passionate"...', 'https://genshin-impact.fandom.com/wiki/Collei%2FProfile', 'A Trainee Forest Ranger who is under the tutelage of Tighnari. She started her academic career a little later than her peers, so she is currently working hard to catch up. She hides the other side of her personality deep under the surface of optimism and kindness.

"Helpful," "bright and sunny," "friendly and passionate"...', 'https://genshin-impact.fandom.com/wiki/Collei%2FProfile', '"¿Eh? ¿Tienes pensado ir a Sumeru? ¿Te importaría pasarte a ver a Collei? Hace tiempo que no la veo. Me pregunto si tiene el pelo más largo. ¿Habrá crecido mucho?"
Guardabosques en prácticas del Bosque Avidya. Es animada, positiva y cariñosa.

Collei es originaria de Sumeru, pero son pocos los que conocen su historia antes de que llegara a la Villa Gandharva.', 'https://genshin-impact.fandom.com/es/wiki/Collei%2FHistoria', false, '[{"desde":20,"hasta":40,"creditos":20000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101213.png","nombre":"Champiñón rukkhashava","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104131.png","nombre":"Pedacito de esmeralda nagadus","cantidad":1},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","nombre":"Flecha robusta","cantidad":3}]},{"desde":40,"hasta":50,"creditos":40000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101213.png","nombre":"Champiñón rukkhashava","cantidad":10},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104132.png","nombre":"Fragmento de esmeralda nagadus","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","nombre":"Flecha robusta","cantidad":15},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113036.png","nombre":"Picogancho fúngico","cantidad":2}]},{"desde":50,"hasta":60,"creditos":60000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101213.png","nombre":"Champiñón rukkhashava","cantidad":20},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104132.png","nombre":"Fragmento de esmeralda nagadus","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","nombre":"Flecha afilada","cantidad":12},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113036.png","nombre":"Picogancho fúngico","cantidad":4}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101213.png","nombre":"Champiñón rukkhashava","cantidad":30},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104133.png","nombre":"Trozo de esmeralda nagadus","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","nombre":"Flecha afilada","cantidad":18},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113036.png","nombre":"Picogancho fúngico","cantidad":8}]},{"desde":70,"hasta":80,"creditos":100000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101213.png","nombre":"Champiñón rukkhashava","cantidad":45},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104133.png","nombre":"Trozo de esmeralda nagadus","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112013.png","nombre":"Flecha veterana","cantidad":12},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113036.png","nombre":"Picogancho fúngico","cantidad":12}]},{"desde":80,"hasta":90,"creditos":120000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101213.png","nombre":"Champiñón rukkhashava","cantidad":60},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104134.png","nombre":"Esmeralda nagadus","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112013.png","nombre":"Flecha veterana","cantidad":24},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113036.png","nombre":"Picogancho fúngico","cantidad":20}]}]'::jsonb),
  ('gi-columbina', 'genshin-impact', 'Columbina', 'https://enka.network/ui/UI_AvatarIcon_Columbina.png', '5', 'Hydro', 90, null, 'Sub-DPS / Support', null, null, false, 'Kuutar, the Moon Goddess of Nod-Krai, and formerly The Damselette, Third of the Fatui Harbingers. Still, her friends call her Columbina Hyposelenia, and she prefers it that way.

Day or night?

Why, night, of course. The world of daylight was filled with too many words beyond her understanding. "Kuutar," "The Damselette," "Goddess"... She knew these words to be like mirrors, each reflecting a version of her in this unfamiliar world. But those were versions others wished to see. She did not recognize herself in those reflections, just as she did not recognize the moon hanging in the sky. At least at night, she could clearly feel the pull coming from beyond the heavens. It made no sound, yet she understood it all the same — the Frost Moon was calling her home.

...

Spring, summer, autumn, or winter?

Winter, without question.', 'https://genshin-impact.fandom.com/wiki/Columbina%2FProfile', 'Kuutar, the Moon Goddess of Nod-Krai, and formerly The Damselette, Third of the Fatui Harbingers. Still, her friends call her Columbina Hyposelenia, and she prefers it that way.

Day or night?

Why, night, of course. The world of daylight was filled with too many words beyond her understanding. "Kuutar," "The Damselette," "Goddess"... She knew these words to be like mirrors, each reflecting a version of her in this unfamiliar world. But those were versions others wished to see. She did not recognize herself in those reflections, just as she did not recognize the moon hanging in the sky. At least at night, she could clearly feel the pull coming from beyond the heavens. It made no sound, yet she understood it all the same — the Frost Moon was calling her home.

...

Spring, summer, autumn, or winter?

Winter, without question.', 'https://genshin-impact.fandom.com/wiki/Columbina%2FProfile', 'Kuutar, la Diosa de la Luna de Nod-Krai y antaño la Damisela, Tercera de los Heraldos Fatui. Aun así, sus amigos la llaman Columbina Hyposelenia, y ella lo prefiere así.

¿Día o noche?

La noche, por supuesto. El mundo de la luz diurna estaba lleno de palabras que escapaban a su comprensión. "Kuutar", "la Damisela", "diosa"... Sabía que esas palabras eran como espejos, y que cada uno reflejaba una versión de ella en aquel mundo ajeno. Pero eran las versiones que otros deseaban ver. No se reconocía en esos reflejos, igual que tampoco reconocía la luna colgada del cielo. Al menos de noche podía sentir con claridad la llamada que venía de más allá de los cielos. No hacía ruido alguno y, sin embargo, la entendía: la Luna de Escarcha la llamaba a casa.

¿Primavera, verano, otoño o invierno?

Invierno, sin ninguna duda.', 'https://genshin-impact.fandom.com/wiki/Columbina%2FProfile', true, '[{"desde":20,"hasta":40,"creditos":20000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101266.png","nombre":"Hierba invernal","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104121.png","nombre":"Pedacito de lazurita varunada","cantidad":1},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","nombre":"Condensado de Slime","cantidad":3}]},{"desde":40,"hasta":50,"creditos":40000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101266.png","nombre":"Hierba invernal","cantidad":10},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104122.png","nombre":"Fragmento de lazurita varunada","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","nombre":"Condensado de Slime","cantidad":15},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113079.png","nombre":"Asta radiante","cantidad":2}]},{"desde":50,"hasta":60,"creditos":60000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101266.png","nombre":"Hierba invernal","cantidad":20},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104122.png","nombre":"Fragmento de lazurita varunada","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","nombre":"Babas de Slime","cantidad":12},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113079.png","nombre":"Asta radiante","cantidad":4}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101266.png","nombre":"Hierba invernal","cantidad":30},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104123.png","nombre":"Trozo de lazurita varunada","cantidad":3},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","nombre":"Babas de Slime","cantidad":18},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113079.png","nombre":"Asta radiante","cantidad":8}]},{"desde":70,"hasta":80,"c