.moe/assets/UI/UI_ItemIcon_113079.png","nombre":"Asta radiante","cantidad":8}]},{"desde":70,"hasta":80,"creditos":100000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101266.png","nombre":"Hierba invernal","cantidad":45},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104153.png","nombre":"Trozo de turquesa vayuda","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","nombre":"Insignia de cuervo dorada","cantidad":12},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113079.png","nombre":"Asta radiante","cantidad":12}]},{"desde":80,"hasta":90,"creditos":120000,"materiales":[{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101266.png","nombre":"Hierba invernal","cantidad":60},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104154.png","nombre":"Turquesa vayuda","cantidad":6},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","nombre":"Insignia de cuervo dorada","cantidad":24},{"icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113079.png","nombre":"Asta radiante","cantidad":20}]}]'::jsonb),
  ('gi-qiqi', 'genshin-impact', 'Qiqi', 'https://enka.network/ui/UI_AvatarIcon_Qiqi.png', '5', 'Cryo', 90, null, 'Support (Healer)', null, null, false, 'An apprentice and herb gatherer at Bubu Pharmacy. "Blessed" by the adepti with a body that cannot die, this petite zombie cannot do anything without first giving herself orders to do it. Qiqi''s memory is like a sieve. Out of necessity, she always carries around a notebook in which she writes anything important that she is sure to forget later. But on her worst days, she even forgets to look at her notebook...

Due to being a zombie, Qiqi lacks facial expression. She hopes that''s okay.

She may look like a zombie, but she''s surprisingly limber due to a strict calisthenics regimen.

Her memory is poor. She forgets easily, and that is partly why she can seem cold to others.

Her appearance is forever frozen at the point of her passing, so estimates of her age are unreliable.

Zombies require orders to act, but due to some reason or another, Qiqi is presently giving herself orders.', 'https://genshin-impact.fandom.com/wiki/Qiqi%2FProfile', 'An apprentice and herb gatherer at Bubu Pharmacy. "Blessed" by the adepti with a body that cannot die, this petite zombie cannot do anything without first giving herself orders to do it. Qiqi''s memory is like a sieve. Out of necessity, she always carries around a notebook in which she writes anything important that she is sure to forget later. But on her worst days, she even forgets to look at her notebook...

Due to being a zombie, Qiqi lacks facial expression. She hopes that''s okay.

She may look like a zombie, but she''s surprisingly limber due to a strict calisthenics regimen.

